-- Keep legacy invalid records inspectable, enforce original transport on new writes.
ALTER TABLE mcp_servers ADD CONSTRAINT mcp_servers_transport_check CHECK(transport IN ('stdio','http','sse')) NOT VALID;
-- MCP command/url are nullable in original DB.SaveMCP (empty -> NULL).
ALTER TABLE mcp_servers ALTER COLUMN command DROP NOT NULL,ALTER COLUMN url DROP NOT NULL;
-- Source host metadata extracted from frozen orchestration/platform tools.
-- Existing user configuration is preserved; explicit reset restores source defaults.
INSERT INTO tool_defaults(key,description,schema,agents) VALUES
('list_tasks','List all tasks(id/Description/Target/Status/Run time/Parent task/LLM Configuration)，Arrangement agent Use it to grasp the overall situation, see which tasks are stuck for too long, and which one to use. LLM。Running time: Running=Create→Now, final state=Create→Last activity(seconds)。llm_profile：Task planner/worker Configuration name used，(Activate configuration)=Follow global activation。','{"properties": {}, "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_llm_profiles','List available LLM Configuration(profile)：id、Name, model, format, whether it is the current active configuration. use id Give spawn_task of llm_profile_id Parameter specified subtask exclusive LLM（Such as using cheap models for reconnaissance and strong models for utilization). Does not contain API Key。','{"properties": {}, "type": "object"}'::jsonb,'["auto"]'::jsonb),
('spawn_task','Create a new subtask and start the exploration engine, return task_id。Used to put one thing(Like a question/A goal)Assign an independent task。parent_ref Optional: Fill in the parent task associated with the current arrangement id Make a father-son relationship。','{"properties": {"description": {"description": "Task Description(Short title)", "type": "string"}, "goal": {"description": "Mission Objective(What to achieve)", "type": "string"}, "llm_profile_id": {"description": "Optional: Specify this subtask planner/worker used LLM Configuration id(See list_llm_profiles)；If left blank, the parent task will be inherited and the global activation configuration will be rolled back.", "type": "integer"}, "parent_ref": {"description": "Optional: Parent task id(Make a father-son relationship)", "type": "string"}, "plan_heartbeat_seconds": {"description": "Optional：planner Heartbeat trigger interval(seconds)。From the end of the last round of planning/The task starts to reach this value and there is no trigger during the period. → Trigger a round of planning(Deadlock + Wake up to supervise in-flight worker)。Leave blank or 0 = Default 600(10min)；", "type": "integer"}, "seed_first_intent": {"description": "Optional: It can be turned on for simple tasks, and a seed intent can be directly sent when creating.(Content=Description+Target)Let worker No need to wait for the first round planner Start running the test directly; default false(Follow standards, plan first and then execute)。", "type": "boolean"}, "source_task_ids": {"description": "Optional: Read-only inherited source tasks id List(Most 8 indivual)。Subtasks can read-only reference assets that have been explored by these tasks/Conclusion as starting point; with parent_ref The pure parent-child pointers are different, this is content inheritance。", "items": {"type": "string"}, "type": "array"}, "timeout_seconds": {"description": "Optional: Task-level timeout(seconds)。Trigger graceful ending after reaching the point and enter timeout Final state; leave blank or 0 = No time limit", "type": "integer"}}, "required": ["description", "goal"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('pause_task','Pause the specified task(Stop it planner/worker Loop)。','{"properties": {"task_id": {"description": "Task to be paused id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_task_graph','Read the exploration graph overview of the specified task(Same as graph_overview：Asset Count/frontier/Discovery/Coverage etc.)，Use task_id Specify task。','{"properties": {"task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_task_findings','Read confirmation vulnerability of specified task(Including flag/PoC；Each strip id/task_id/intent_id/vulnclass/severity/Abstract/Status)，Use task_id Specify task。','{"properties": {"task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('add_task_hint','Inject strategic hints into designated tasks(The task’s planner Will be read when generating intent in next round)。
★Priority batch: put multiple prompts in hints Array is submitted once (return ids Array, with hints Equal length and same order, failed items id=0）；Omit if single item hints Directly to the top level text。','{"properties": {"asset_ids": {"description": "Anchored Asset id（Optional，0/1/Multiple; assets within this task id）", "items": {"type": "integer"}, "type": "array"}, "hints": {"description": "【Use this first] Prompt array, each element field is the same as the top level（text/asset_ids/traffic_refs）。", "items": {"properties": {"asset_ids": {"items": {"type": "integer"}, "type": "array"}, "text": {"description": "Prompt content", "type": "string"}, "traffic_refs": {"description": "Optional: Traffic references that have been verified and correspond to the specific vulnerabilities in this tip, and the order is retained; after handover report_finding Transferable evidence_hint_id Carrying these references。", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "type": "object"}, "type": "array"}, "task_id": {"description": "Task id", "type": "string"}, "text": {"description": "[Single] Prompt content", "type": "string"}, "traffic_refs": {"description": "Optional: Traffic references that have been verified and correspond to the specific vulnerabilities in this tip, and the order is retained; after handover report_finding Transferable evidence_hint_id Carrying these references。", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_task_worker_trace','Look at a certain task in the specified task work(Intent)execution process：get_task_worker_trace(task_id, intent_id) Read the step summary; then take step_ids=[...] Get the complete content of those steps(At most once 5 indivual,Multi-pass only returns the previous 5 indivual)。','{"properties": {"intent_id": {"description": "Intent id(In this task work)", "type": "integer"}, "step_ids": {"description": "Optional: Steps to obtain complete content id(At most once 5 indivual,Multi-pass only returns the previous 5 indivual,The rest are in omitted_step_ids listed in)", "items": {"type": "integer"}, "type": "array"}, "task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id", "intent_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_task_worker_traces','List which tasks have been run in the specified task work(Intent) + The respective number of steps used to discover which work Worth reading(Reuse get_task_worker_trace)。','{"properties": {"task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('search_task_worker_traces','Search all tasks by keyword work execution process(Return hit step summary + intent_id)。','{"properties": {"q": {"description": "Search keyword", "type": "string"}, "task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id", "q"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_task_node_detail','Read the complete content of an exploration graph node in the specified task(Discovery/Facts/Intent/Objective: Abstract + Details/Evidence/PoC)。id is the exploration node id(Such as report_finding Return, or list_task_findings in id)。Use this to obtain complete evidence of the vulnerability before writing a vulnerability report。','{"properties": {"id": {"description": "Explore graph nodes id(Non-Asset id)", "type": "integer"}, "task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id", "id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_finding_report','Write for registered vulnerabilities/Update [detailed report】(Markdown Full text,Overwrite old content in entire section)。finding_id Pass report_finding The one returned The number in id("finding recorded: <id>" numbers in)。Report recommendations include:Vulnerability overview, impact and harm, reproduction steps, evidence/PoC、Repair suggestions。','{"properties": {"evidence_version": {"description": "get_finding_traffic Returned Evidence version；Used to prevent reports from covering new evidence changes", "type": "integer"}, "finding_id": {"description": "Target vulnerability id(report_finding Returned id)", "type": "integer"}, "report": {"description": "Full text of detailed report,Markdown Format", "type": "string"}}, "required": ["finding_id", "report"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_finding_traffic','Read the real traffic evidence bound to the vulnerability without relying on the capture switch。finding_id Use report_finding JSON Independent vulnerability records returned ID（An exploration node that is not the first row ID）。Don’t pass it yet binding_id Get the list and version；Empty list is normal，TCP Wait for Fei HTTP Vulnerabilities or text can still be used when not collected/Command evidence writing report, do not force binding. Press when bound binding_id、side(request/response)、offset Read the text in segments. will be read when writing the report version as evidence_version Pass to update_finding_report，The latter finding_id Still using exploration nodes ID。','{"properties": {"binding_id": {"description": "Bindings in manifest ID，If omitted, return to list", "type": "string"}, "finding_id": {"description": "Independent vulnerability record ID", "type": "string"}, "length": {"type": "integer"}, "offset": {"type": "integer"}, "side": {"description": "request or response，Default response", "type": "string"}}, "required": ["finding_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('bind_finding_traffic','Patch registered vulnerabilities with verified and authentic HTTP Traffic。finding_id Use independent vulnerability records ID；Do not pass exploration nodes ID。All references in the same batch succeed or all fail. Repeated references do not cover existing instructions. Patching will mark existing reports for update; do not re-detect or re-create vulnerabilities for patching.。','{"properties": {"finding_id": {"description": "Independent vulnerability record ID，From list_task_findings / get_task_node_detail of finding_id Field reading", "type": "string"}, "traffic_refs": {"description": "Optional: Traffic references that have been verified and correspond to the specific vulnerabilities in this tip, and the order is retained; after handover report_finding Transferable evidence_hint_id Carrying these references。", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "required": ["finding_id", "traffic_refs"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('create_skill','Create a new skill(Write SKILL.md，agentskills.io Specification)。name Lowercase letters/Number/Hyphen。','{"properties": {"description": {"description": "skill Description(Required, describe what it does/When to use)", "type": "string"}, "instructions": {"description": "Markdown Text description(Optional)", "type": "string"}, "name": {"description": "skill Name(Starting with a lowercase letter, the letter/Number/Hyphen)", "type": "string"}}, "required": ["name", "description"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_skill_file','Write/Overwrite a A file within skill a file within(Default SKILL.md)。Used to modify skill content or add scripts/Quote。','{"properties": {"content": {"description": "Complete file content", "type": "string"}, "file": {"description": "Relative path(Optional, default SKILL.md，Such as scripts/run.py)", "type": "string"}, "name": {"description": "skill Name", "type": "string"}}, "required": ["name", "content"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('create_custom_tool','【Important] When installing some tools that are not available on the platform, call this tool to put the installed tools into the platform so that the platform can call it! Create a custom tool(shell/command/script/http)。shell=bash Environmental Statement, only key+description+agents，No need exec/schema。','{"properties": {"agents": {"description": "Bound agent key(Optional)", "items": {"type": "string"}, "type": "array"}, "deferred": {"description": "Whether to delay(shell Invalid type; only command/script/http Open only with uncommon tools)", "type": "boolean"}, "description": {"description": "Description sent to model", "type": "string"}, "enabled": {"description": "Whether to enable(Default true)", "type": "boolean"}, "exec": {"description": "Execution Specifications(shell Type not required): command→{command}; script→{code}; http→{method,url,headers,body,proxy,use_recording_proxy}", "type": "object"}, "key": {"description": "Tool key(Starting with a lowercase letter, the letter/Number/Underline)", "type": "string"}, "kind": {"description": "shell | command | script(OnlyPython) | http。shell=bash Environmental Statement(Only inform the model that the tool is available in bash directly call, no need to exec/schema)；The remaining three types need to be provided exec", "type": "string"}, "schema": {"description": "Parameters JSON-Schema(shell/command/script Can be left blank; http Required and included properties)", "type": "object"}}, "required": ["key", "kind"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_custom_tool','Modify an existing custom tool(Press key)。','{"properties": {"agents": {"description": "Bound agent key(Optional)", "items": {"type": "string"}, "type": "array"}, "deferred": {"description": "Whether to delay(shell Invalid type; only command/script/http Open only with uncommon tools)", "type": "boolean"}, "description": {"description": "Description sent to model", "type": "string"}, "enabled": {"description": "Whether to enable(Default true)", "type": "boolean"}, "exec": {"description": "Execution Specifications(shell Type not required): command→{command}; script→{code}; http→{method,url,headers,body,proxy,use_recording_proxy}", "type": "object"}, "key": {"description": "Custom tool to modify key", "type": "string"}, "kind": {"description": "shell | command | script(OnlyPython) | http。shell=bash Environmental Statement(Only inform the model that the tool is available in bash directly call, no need to exec/schema)；The remaining three types need to be provided exec", "type": "string"}, "schema": {"description": "Parameters JSON-Schema(shell/command/script Can be left blank; http Required and included properties)", "type": "object"}}, "required": ["key", "kind"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('create_mcp','Create a MCP Server(stdio/http/sse)。After creation, its tool needs to be pressed agent Visibility Grant。','{"properties": {"args": {"description": "Command parameter array Start command for", "items": {"type": "string"}, "type": "array"}, "command": {"description": "stdio startup command(Such as npx)", "type": "string"}, "enabled": {"description": "Whether to enable(Default true)", "type": "boolean"}, "env": {"description": "Environment variables {KEY:VALUE}", "type": "object"}, "insecure": {"description": "http: Skip TLS Certificate verification(Self-signed certificate time setting true, Default false)", "type": "boolean"}, "name": {"description": "MCP Server name", "type": "string"}, "transport": {"description": "stdio | http / sse", "type": "string"}, "url": {"description": "http/sse of URL", "type": "string"}}, "required": ["name", "transport"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_mcp','Modify an existing MCP Server(Press id)。','{"properties": {"args": {"description": "Command parameter array Start command for", "items": {"type": "string"}, "type": "array"}, "command": {"description": "stdio startup command(Such as npx)", "type": "string"}, "enabled": {"description": "Whether to enable(Default true)", "type": "boolean"}, "env": {"description": "Environment variables {KEY:VALUE}", "type": "object"}, "id": {"description": "To be modified MCP Server id", "type": "integer"}, "insecure": {"description": "http: Skip TLS Certificate verification(Self-signed certificate time setting true, Default false)", "type": "boolean"}, "name": {"description": "MCP Server name", "type": "string"}, "transport": {"description": "stdio | http / sse", "type": "string"}, "url": {"description": "http/sse of URL", "type": "string"}}, "required": ["id", "name", "transport"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('delete_assets_by_host','Press host Exact asset deletion: Delete the Domain name of host domain name/Subdomain name, and services under it(service)、Interface(endpoint)。
host Exact match(Lowercase, remove spaces)，Not blurry/Wildcard。
Transfer root domain name(Such as example.com)Its subdomain name and its services will also be deleted./Interface; pass subdomain name(Such as a.example.com)or IP Delete only this host Self and its services/Interface。
⚠️ Hard deletion, applied to global asset library(Cross-task sharing)、Irrevocable。','{"properties": {"host": {"description": "To be deleted host：Domain name/Subdomain name/IP。Exact match, such as example.com or a.example.com or 1.2.3.4", "type": "string"}}, "required": ["host"], "type": "object"}'::jsonb,'["auto"]'::jsonb)
ON CONFLICT(key) DO UPDATE SET description=EXCLUDED.description,schema=EXCLUDED.schema,agents=EXCLUDED.agents;
INSERT INTO tools(key,description,schema,agents,system,kind)
SELECT key,description,schema,CASE WHEN key='bind_finding_traffic' THEN '["reporter","auto"]'::jsonb ELSE agents END,TRUE,'builtin'
FROM tool_defaults WHERE key IN('list_tasks','list_llm_profiles','spawn_task','pause_task','get_task_graph','list_task_findings','add_task_hint','get_task_worker_trace','list_task_worker_traces','search_task_worker_traces','get_task_node_detail','update_finding_report','get_finding_traffic','bind_finding_traffic','create_skill','update_skill_file','create_custom_tool','update_custom_tool','create_mcp','update_mcp','delete_assets_by_host') ON CONFLICT(key) DO NOTHING;
